import Foundation
import SwiftUI
import UIKit

/// Bundled MF Workouts data (read-only, `shared/catalog/` generated by `scripts/catalog.ts`) merged with the owner's
/// custom exercises.
@MainActor @Observable
final class ExerciseCatalog {
    private(set) var bundled: [Exercise]
    private var byID: [ExerciseID: Exercise]
    private(set) var custom: [Exercise] = []
    let equipment: [String: Equipment]
    let articles: [String: Article]

    init() {
        let decoded: [Exercise] = Self.load("exercises")
        bundled = decoded.sorted { $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending }
        byID = Dictionary(uniqueKeysWithValues: decoded.map { ($0.id, $0) })
        equipment = Dictionary(uniqueKeysWithValues: (Self.load("equipment") as [Equipment]).map { ($0.id, $0) })
        articles = Dictionary(uniqueKeysWithValues: (Self.load("articles") as [Article]).map { ($0.id, $0) })
    }

    /// `shared/catalog/`, copied into the bundle as a folder so the JSON's relative paths resolve unchanged.
    nonisolated static let root: URL = {
        guard let url = Bundle.main.url(forResource: "catalog", withExtension: nil) else {
            fatalError("The app bundle has no catalog folder. Regenerate `shared/catalog/` with `bun scripts/catalog.ts`.")
        }
        return url
    }()

    nonisolated static func load<T: Decodable>(_ name: String) -> T {
        do {
            return try JSONDecoder().decode(T.self, from: Data(contentsOf: root.appending(path: "\(name).json")))
        } catch {
            fatalError("catalog/\(name).json is missing or does not match its Swift type: \(error)")
        }
    }

    /// Markdown with "Setting up", "Exercise technique", and "Description" sections.
    func instructions(for exercise: Exercise) -> String? {
        exercise.instructionsFile.flatMap(Self.markdown)
    }

    func articleText(_ article: Article) -> String? { Self.markdown(article.file) }

    private static func markdown(_ path: String) -> String? {
        try? String(contentsOf: root.appending(path: path), encoding: .utf8)
    }

    /// Decoded catalog images by path, shared by every thumbnail.
    static func image(_ path: String?) -> UIImage? {
        guard let path else { return nil }
        if let hit = imageCache.object(forKey: path as NSString) { return hit }
        guard let image = UIImage(contentsOfFile: root.appending(path: path).path) else { return nil }
        imageCache.setObject(image, forKey: path as NSString)
        return image
    }

    private static let imageCache = NSCache<NSString, UIImage>()

    var all: [Exercise] { custom + bundled }

    /// Called by the app whenever the `CustomExercise` store changes.
    func setCustom(_ exercises: [Exercise]) {
        for old in custom { byID[old.id] = nil }
        custom = exercises
        for exercise in exercises { byID[exercise.id] = exercise }
    }

    func exercise(_ id: ExerciseID) -> Exercise? { byID[id] }

    /// Name for display even when an ID no longer resolves, so history never shows a blank row.
    func name(_ id: ExerciseID) -> String { byID[id]?.name ?? "Unknown exercise" }
}

/// One of an exercise's position frames from the bundle, or a muscle-colored placeholder.
struct ExerciseImage: View {
    let exercise: Exercise
    var frame = 0

    var body: some View {
        if let image = ExerciseCatalog.image(exercise.images[safe: frame]) {
            Image(uiImage: image).resizable().scaledToFill()
        } else {
            ZStack {
                Theme.surfaceRaised
                Image(systemName: "figure.strengthtraining.traditional")
                    .font(.system(size: 24))
                    .foregroundStyle(Theme.textTertiary)
            }
        }
    }
}

extension Array {
    subscript(safe index: Int) -> Element? { indices.contains(index) ? self[index] : nil }
}
